/* ============================================
   STAT COMPONENT
   A single headline metric with label and an
   optional trend delta. Compose in a row for
   a metrics band.
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

.ds-stat {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--gap-050);
}

/* ============================================
   VALUE — the display tier's weight (300 in the
   base theme), so numerals follow the theme
   ============================================ */

.ds-stat__value {
  font-family: var(--font-sub-display-family);
  font-size: var(--font-sub-display-size);
  font-weight: var(--font-sub-display-weight);
  line-height: var(--font-sub-display-line-height);
  letter-spacing: var(--font-sub-display-letter-spacing);
  color: var(--color-text-display);
}

.ds-stat--large .ds-stat__value {
  font-family: var(--font-display-2-family);
  font-size: var(--font-display-2-size);
  line-height: var(--font-display-2-line-height);
  letter-spacing: var(--font-display-2-letter-spacing);
}

/* ============================================
   HEAD — an icon tile and a caption above the
   value. A headed stat fills its tile's width,
   so the caption reaches the far end.
   ============================================ */

.ds-stat--headed {
  display: flex;
  gap: var(--gap-050);
}

.ds-stat__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap-200);
  align-self: stretch;
  /* The head sits --gap-300 above the value: the stat's own row gap
     (--gap-050) plus this margin. */
  margin-block-end: calc(var(--gap-300) - var(--gap-050));
}

/* A node passed as the icon sits where Icon's tile would. */
.ds-stat__icon {
  flex-shrink: 0;
}

.ds-stat__caption {
  margin-inline-start: auto;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  letter-spacing: var(--font-caption-letter-spacing);
  color: var(--color-text-tertiary);
}

/* What follows the figures (a Sparkline, an AvatarGroup) runs the stat's width. */
.ds-stat__extra {
  display: block;
  align-self: stretch;
  margin-block-start: var(--gap-200);
}

/* ============================================
   LABEL
   ============================================ */

.ds-stat__label {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
}

/* A caption placed under the label: the label's area holds both lines,
   so every placement's grid keeps its areas. */
.ds-stat__label--captioned {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.ds-stat__label--captioned .ds-stat__caption {
  margin-inline-start: 0;
}

/* ============================================
   DELTA — trend-coloured annotation
   ============================================ */

/* The arrow sits on the delta's first line, not the middle of its whole
   height, so a delta that wraps keeps its arrow beside its opening words. */
.ds-stat__delta {
  display: inline-flex;
  align-items: flex-start;
  gap: var(--gap-050);
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
}

.ds-stat__delta .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
  line-height: 1;
  flex-shrink: 0;
  /* Centred on one line of the delta's text, whatever a theme makes of the
     line height and the icon size. */
  margin-block-start: calc((var(--font-paragraph-sm-emphasis-line-height) - var(--icon-size)) / 2);
}

/* The trend tokens are theme-split for contrast: the brightest ramp steps
   that hold AA on the primary container, the mint/coral accents on dark ones. */
.ds-stat__delta--up {
  color: var(--color-trend-up);
}

.ds-stat__delta--down {
  color: var(--color-trend-down);
}

.ds-stat__delta--neutral {
  color: var(--color-text-tertiary);
}

/* ============================================
   INLINE DELTA — delta to the right of the
   value, bottom-aligned to its baseline
   ============================================ */

.ds-stat--delta-inline {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas:
    'value delta'
    'label label';
  column-gap: var(--gap-200);
  row-gap: var(--gap-050);
}

/* A head and the extras run the grid's full width, above and below. */
.ds-stat--delta-inline.ds-stat--headed {
  grid-template-areas:
    'head head'
    'value delta'
    'label label';
}

.ds-stat--delta-inline .ds-stat__head {
  grid-area: head;
}

.ds-stat--delta-inline .ds-stat__extra {
  grid-column: 1 / -1;
}

.ds-stat--delta-inline .ds-stat__value {
  grid-area: value;
}

.ds-stat--delta-inline .ds-stat__label {
  grid-area: label;
}

.ds-stat--delta-inline .ds-stat__delta {
  grid-area: delta;
  align-self: end;
  justify-self: start;
  /* Optical baseline: compensates the display value's half-leading. */
  margin-bottom: var(--gap-100);
}

/* ============================================
   AUTO DELTA — inline while the stat has room,
   stacked under the label once it is narrow.
   The root fills its parent and is the size
   container; the body inside it re-templates.
   ============================================ */

.ds-stat--delta-auto {
  display: block;
  width: 100%;
  min-width: 0;
  container: ds-stat / inline-size;
}

/* The auto root is a block, with no row gap: the margin is the whole space. */
.ds-stat--delta-auto .ds-stat__head {
  margin-block-end: var(--gap-300);
}

/* A wrapping row, not a fixed grid: the delta sits beside the value while
   the two fit and wraps onto its own line the moment they do not, so a
   wide value (a long figure, a monospace theme's numerals) never pushes
   the delta past the tile's edge at any width. The label takes a whole
   line of its own, always last. */
.ds-stat__body {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  column-gap: var(--gap-200);
  row-gap: var(--gap-050);
}

.ds-stat__body .ds-stat__value {
  order: 0;
  min-width: 0;
}

.ds-stat__body .ds-stat__delta {
  order: 1;
  /* The inline placement's optical baseline. */
  margin-bottom: var(--gap-100);
}

.ds-stat__body .ds-stat__label {
  order: 2;
  flex-basis: 100%;
}

/* Too narrow for the value and its delta side by side: the delta drops
   under the label, the stacked placement's order. */
@container ds-stat (max-width: 180px) {
  .ds-stat__body {
    flex-direction: column;
    align-items: flex-start;
  }

  .ds-stat__body .ds-stat__delta {
    order: 3;
    margin-bottom: 0;
  }
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-stat .material-symbols-rounded {
  color: inherit;
}

} /* @layer rift.components */

import React from 'react';
import './Stat.css';
import '../../fonts/material-symbols.css';
import { DEFAULT_LOCALE, formatNumber } from '../../behaviors/locale';
import { Icon } from '../Icon/Icon';

/** Props owned by Stat itself — everything else falls through to the root div. */
type StatOwnProps = {
  /** The headline number, e.g. "~900%" or "3.8M" — or a node, such as an AnimatedNumber, for figures that move */
  value: React.ReactNode;
  /** What the number measures */
  label: string;
  /** Optional change annotation, e.g. "+42% vs last quarter" */
  delta?: string;
  /** Direction of the delta — colours it and adds an arrow */
  trend?: 'up' | 'down' | 'neutral';
  /**
   * Where the delta sits: stacked below the label, inline to the right of the
   * value (bottom-aligned), or `auto`: inline while the stat has room and
   * stacked once it is narrow, such as a KPI tile in a two-up phone grid.
   * `auto` fills its parent's width and reads its own, so it restacks
   * wherever it sits, whatever the viewport.
   */
  deltaPlacement?: 'stacked' | 'inline' | 'auto';
  /** Stat size */
  size?: 'default' | 'large';
  /** A decorative mark in a round tile above the value, naming what the metric is about: a Material Symbol name (string) or a node. */
  icon?: string | React.ReactNode;
  /** A short note at the far end of the top row, in the caption face: the period the figure covers ("Last 30 days"), its source. */
  caption?: React.ReactNode;
  /**
   * Where the caption sits: `head`, at the far end of the top row beside the
   * icon, or `label`, a second line under the label. Defaults to `head`.
   */
  captionPlacement?: 'head' | 'label';
  /** Shown after the value, label and delta, such as a Sparkline of the metric's recent history or an AvatarGroup of who it counts. */
  children?: React.ReactNode;
  /** The BCP 47 locale a number `value` is written in, such as `ar-EG`. Defaults to `en-US`. This component can render from a Server Component, so it takes the prop alone and reads no LocaleProvider. */
  locale?: string;
  /** Additional CSS classes */
  className?: string;
};

export interface StatProps
  extends StatOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof StatOwnProps> {}

const TREND_ICONS: Record<NonNullable<StatOwnProps['trend']>, string> = {
  up: 'arrow_upward',
  down: 'arrow_downward',
  neutral: 'remove',
};

/**
 * Stat component — a single headline metric with a label and an
 * optional trend delta. Compose several in a row for a metrics band.
 * Forwards a ref to the root div and spreads native attributes onto it.
 */
export const Stat = React.forwardRef<HTMLDivElement, StatProps>(
  (
    {
      value,
      label,
      delta,
      trend = 'neutral',
      deltaPlacement = 'stacked',
      size = 'default',
      icon,
      caption,
      captionPlacement = 'head',
      children,
      locale = DEFAULT_LOCALE,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-stat';
    const hasIcon = icon != null && icon !== false && icon !== '';
    const hasCaption = caption != null && caption !== false && caption !== '';
    const captionInHead = hasCaption && captionPlacement === 'head';
    const captionInLabel = hasCaption && captionPlacement === 'label';
    const hasHead = hasIcon || captionInHead;

    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      deltaPlacement === 'inline' ? `${baseClass}--delta-inline` : '',
      deltaPlacement === 'auto' ? `${baseClass}--delta-auto` : '',
      hasHead ? `${baseClass}--headed` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const parts = (
      <>
        <span className={`${baseClass}__value`}>{typeof value === 'number' ? formatNumber(value, locale) : value}</span>
        {captionInLabel ? (
          <span className={`${baseClass}__label ${baseClass}__label--captioned`}>
            <span className={`${baseClass}__label-text`}>{label}</span>
            <span className={`${baseClass}__caption`}>{caption}</span>
          </span>
        ) : (
          <span className={`${baseClass}__label`}>{label}</span>
        )}
        {delta && (
          <span className={`${baseClass}__delta ${baseClass}__delta--${trend}`}>
            <span className="material-symbols-rounded" aria-hidden="true">
              {TREND_ICONS[trend]}
            </span>
            {delta}
          </span>
        )}
      </>
    );

    return (
      <div {...rest} ref={ref} className={classes}>
        {/* A container query styles only what sits inside the container,
            so `auto` lays its parts out on an inner body the root measures. */}
        {hasHead && (
          <span className={`${baseClass}__head`}>
            {hasIcon &&
              (typeof icon === 'string' ? (
                <Icon name={icon} size="500" tile className={`${baseClass}__icon`} />
              ) : (
                <span className={`${baseClass}__icon`} aria-hidden="true">
                  {icon}
                </span>
              ))}
            {captionInHead && <span className={`${baseClass}__caption`}>{caption}</span>}
          </span>
        )}
        {deltaPlacement === 'auto' ? <span className={`${baseClass}__body`}>{parts}</span> : parts}
        {children != null && children !== false && <span className={`${baseClass}__extra`}>{children}</span>}
      </div>
    );
  },
);

Stat.displayName = 'Stat';
